import math

def f(n):
    """Calculates f(n) = n / 2^m, where 2^m is the highest power of 2 dividing n.
    This is equivalent to the odd part of n.
    """
    if n == 0:
        return 0 # Should not happen for positive integers
    m = 0
    temp_n = n
    while temp_n > 0 and temp_n % 2 == 0:
        m += 1
        temp_n //= 2
    return temp_n

def check_condition(u, v):
    """Checks if the condition holds for given u and v."""
    # The condition must hold for k = 0, 1, ..., v-1
    for k in range(v):
        n1 = u + k
        n2 = u + v + k

        # Check f(u+v+k) - f(u+k) is a multiple of 4
        diff = f(n2) - f(n1)
        if diff % 4 != 0:
            return False
    return True

v_values = [7, 9]
max_u = 50
solutions = {}

for v in v_values:
    found_u = []
    for u in range(1, max_u + 1):
        if check_condition(u, v):
            found_u.append(u)
    solutions[v] = found_u

print("--- Search Results ---")
for v, u_list in solutions.items():
    print(f"v={v}: Found {len(u_list)} solutions for u <= {max_u}. Solutions: {u_list}")
